import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {Script} from 'node:vm';
import {DesignerStore} from './store.js';
import {WorkspaceService,migrateWorkbench,WORKSPACE_ACTIONS} from './workspace-service.js';

// Strict public Fs/Shell test doubles: all mutations require explicit policy and CAS.
class MemoryFS {
  files=new Map();aliases=new Map();writes=[];counter=0;
  async resolve(value,{cwd='/workspace'}={}){let full=path.resolve(cwd,value);for(const [from,to]of this.aliases)if(full===from||full.startsWith(from+'/'))full=to+full.slice(from.length);return {targetKey:full,displayPath:full};}
  processPath(t){return t.displayPath;}
  contains(a,b){return b.targetKey===a.targetKey||b.targetKey.startsWith(a.targetKey+'/');}
  async stat(t){const f=this.files.get(t.targetKey);return f?{type:'file',version:f.version,size:f.bytes.length}:[...this.files.keys()].some(k=>k.startsWith(t.targetKey+'/'))?{type:'directory',version:'dir'}:undefined;}
  async readBytes(t,signal,max){signal?.throwIfAborted();const f=this.files.get(t.targetKey);if(!f)throw Object.assign(Error('missing'),{code:'FS_NOT_FOUND'});if(f.bytes.length>max)throw Object.assign(Error('large'),{code:'FS_TOO_LARGE'});return Buffer.from(f.bytes);}
  byteRangeReads=[];
  async readByteRange(t,range,signal){signal?.throwIfAborted();this.byteRangeReads.push(range);const f=this.files.get(t.targetKey);if(!f)throw Object.assign(Error('missing'),{code:'FS_NOT_FOUND'});return Buffer.from(f.bytes.subarray(range.offset,range.offset+range.length));}
  async readText(t){return (await this.readBytes(t,undefined,100*1024*1024)).toString('utf8');}
  async listDir(t){const result=new Map();for(const k of this.files.keys())if(k.startsWith(t.targetKey+'/')){const tail=k.slice(t.targetKey.length+1),name=tail.split('/')[0],target=await this.resolve(t.targetKey+'/'+name);result.set(name,{name,target,type:tail.includes('/')?'directory':'file',version:tail.includes('/')?undefined:this.files.get(k).version});}return [...result.values()].sort((a,b)=>a.name.localeCompare(b.name));}
  permit(t,policy){assert.ok(policy,'explicit policy required');if(policy.mode==='read-only'||policy.mode==='workspace-write'&&!this.contains({targetKey:policy.workspaceRoot},t))throw Object.assign(Error('denied'),{code:'FS_SANDBOX_DENIED'});}
  async writeText(t,value,intent,signal,policy){signal?.throwIfAborted();this.permit(t,policy);assert.ok(intent,'CAS required');const before=this.files.get(t.targetKey);if(intent.kind==='createIfAbsent'?!!before:before?.version!==intent.version)throw Object.assign(Error('stale'),{code:'FS_STALE_VERSION'});const version=String(++this.counter);this.files.set(t.targetKey,{bytes:Buffer.from(value),version});this.writes.push({path:t.targetKey,policy,intent});return {version,operation:before?'update':'create',before:before?.bytes.toString()||null,after:value};}
  async deleteFile(t,expected,signal,policy){signal?.throwIfAborted();this.permit(t,policy);assert.ok(expected?.version);const f=this.files.get(t.targetKey);if(f?.version!==expected.version)throw Object.assign(Error('stale'),{code:'FS_STALE_VERSION'});this.files.delete(t.targetKey);this.writes.push({path:t.targetKey,policy,intent:expected});return {before:f.bytes.toString()};}
  async moveFile(a,b,options,signal,policy){this.permit(a,policy);this.permit(b,policy);assert.equal(options.expectedDestination.kind,'createIfAbsent');const f=this.files.get(a.targetKey);if(f?.version!==options.expectedSource?.version||this.files.has(b.targetKey))throw Object.assign(Error('stale'),{code:'FS_STALE_VERSION'});const destination=await this.writeText(b,f.bytes.toString(),options.expectedDestination,signal,policy);await this.deleteFile(a,options.expectedSource,signal,policy);return {destination,sourceBefore:f.bytes.toString(),sourceDeleted:true};}
  async external(p,value){const t=await this.resolve(p);const old=this.files.get(t.targetKey);return this.writeText(t,value,old?{kind:'replaceIfVersion',version:old.version}:{kind:'createIfAbsent'},undefined,{mode:'danger-full-access',workspaceRoot:'/workspace'});}
}
const policy={mode:'workspace-write',workspaceRoot:'/workspace'};
const code=c=>e=>e.code===c;
function fixture(){const fs=new MemoryFS(),store=new DesignerStore({fs,workspaceRoot:'/workspace',policy:()=>policy}),shellCalls=[];const owner={store,ctx:{fs,shell:{resolve(spec){shellCalls.push(spec);assert.doesNotThrow(()=>new Script(spec.command.slice("node -e '".length,-1).split("'\\''").join("'")));return spec;},async execute(spec){const x=JSON.parse(spec.stdin),target=await fs.resolve(x.target);fs.permit(target,spec.sandboxPolicy);assert.equal(x.intent,'createIfAbsent');const bytes=Buffer.from(x.bytesBase64,'base64');assert.equal(createHash('sha256').update(bytes).digest('hex'),x.sha256);if(fs.files.has(x.target))return {result:async()=>({exitCode:1,stderr:{text:'ALREADY_EXISTS'},stdout:{text:''}})};fs.files.set(x.target,{bytes,version:String(++fs.counter)});return {result:async()=>({exitCode:0,stderr:{text:''},stdout:{text:'ok'},aborted:false,timedOut:false})};}}},policy:()=>policy};return {fs,store,owner,service:new WorkspaceService(owner),shellCalls};}
const html='<html><body><main data-dsh-node="stable-node">Original</main></body></html>';
async function init(f,name='Project'){return f.service.execute({action:'project.initialize',name},{user:true,policy});}
async function mutate(f,projectId,action,fields={},env={}){const p=await f.service.project(projectId);return f.service.execute({action,projectId,expectedRevision:p.revision,...fields},{policy,user:true,...env});}
async function makeDesign(f,p,name='Web',platform='web'){return mutate(f,p,'design.create',{name,platform});}
async function makePage(f,p,d,name='Page',value=html){return mutate(f,p,'page.create',{designId:d,name,html:value});}

test('action help exposes concrete progressive contracts',async()=>{const f=fixture(),help=await f.service.execute({action:'help'});assert.ok(Object.keys(WORKSPACE_ACTIONS).length>35);assert.ok(help.actions['file.write'].expectedVersion);assert.ok(help.actions['binding.apply'].designIds);});

test('legacy migration is deterministic, read-only and preserves IDs, hashes, paths and complete history',async()=>{const f=fixture();const p=await f.store.projectCreate({name:'Legacy'});const made=await f.store.artboardCreate({projectId:p.id,expectedRevision:1,name:'Old',html});const before=JSON.stringify((await f.store.projectRecord(p.id)).value);const writes=f.fs.writes.length;const a=await f.service.execute({action:'workspace.open',projectId:p.id}),b=await f.service.execute({action:'workspace.open',projectId:p.id});assert.equal(f.fs.writes.length,writes);assert.equal(a.designs[0].id,b.designs[0].id);assert.equal(a.pages[0].id,made.artboard.id);assert.equal(a.pages[0].htmlPath,made.artboard.htmlPath);assert.equal(a.pages[0].contentHash,made.artboard.contentHash);assert.deepEqual(a.project.history,made.project.history);assert.equal(JSON.stringify((await f.store.projectRecord(p.id)).value),before);assert.deepEqual(migrateWorkbench(a.project),a.project);const saved=await mutate(f,p.id,'design.update',{designId:a.designs[0].id,name:'Renamed'});assert.equal(saved.pages[0].id,made.artboard.id);assert.equal((await f.store.artboardGet(p.id,made.artboard.id)).html,html);});

test('initialization creates a real Web page and empty requirements/rules, respecting existing documents',async()=>{const f=fixture(),made=await init(f);assert.equal(made.designs.length,1);assert.equal(made.pages.length,1);assert.equal(made.design.platform,'web');assert.equal(made.page.htmlPath,made.design.folder+'/index.html');assert.equal(made.page.id,made.artboard.id);assert.equal((await f.service.execute({action:'file.read',projectId:made.project.id,path:'docs/requirements.md'})).text,'');assert.equal((await f.service.execute({action:'file.read',projectId:made.project.id,path:'docs/rules.md'})).text,'');const read=await f.service.execute({action:'file.read',projectId:made.project.id,path:'docs/requirements.md'});await mutate(f,made.project.id,'file.write',{fileId:read.fileId,expectedVersion:read.version,content:'Actual user requirements'});const initialized=await mutate(f,made.project.id,'project.initialize',{goal:'new goal',start:{kind:'mastergo',url:'https://mastergo.com/file/example'}});assert.equal(initialized.start.status,'pending-source');assert.equal((await f.service.execute({action:'file.read',projectId:made.project.id,fileId:read.fileId})).text,'Actual user requirements');assert.deepEqual(initialized.designs,made.designs);assert.deepEqual(initialized.pages,made.pages);assert.equal(initialized.page.id,made.page.id);assert.ok(f.fs.writes.every(w=>w.policy&&w.intent));});

test('readable design directories avoid existing names and retain the initial guide', async () => {
  const f = fixture(), initial = await init(f), projectId = initial.project.id;
  assert.equal(initial.design.folder, 'designs/web');
  const read = await f.service.execute({action: 'file.read', projectId, path: initial.page.htmlPath});
  assert.match(read.text, /从这里开始设计/);
  assert.doesNotMatch(read.text, /<(?:script|link)\b/);
  const second = (await makeDesign(f, projectId, 'Web')).design;
  assert.equal(second.folder, 'designs/web-2');
  await mutate(f, projectId, 'design.delete', {designId: second.id});
  const third = (await makeDesign(f, projectId, 'WEB')).design;
  assert.equal(third.folder, 'designs/web-3');
  const project = await f.service.project(projectId);
  const occupied = await f.service.target(project, 'designs/landing/index.html');
  await f.fs.external(occupied.displayPath, '<html><body>Existing file</body></html>');
  const landing = (await makeDesign(f, projectId, 'Landing')).design;
  assert.equal(landing.folder, 'designs/landing-2');
  assert.equal(f.fs.files.get(occupied.displayPath).bytes.toString(), '<html><body>Existing file</body></html>');
});

test('new designs have a prepared root canvas page, durable asset/css/js directories and compatible additional pages',async()=>{
  const f=fixture(),made=await init(f),p=made.project.id,calls=[];f.owner.preparePageHtml=async(value,context)=>{calls.push(context);return {html:value.replace('</body>','<main>Prepared initial page</main></body>')};};
  for(const platform of ['web','mobile']){
    const result=await makeDesign(f,p,platform,platform),{design,page}=result;assert.deepEqual(design.pageIds,[page.id]);assert.equal(page.htmlPath,design.folder+'/index.html');assert.equal(page.designId,design.id);assert.deepEqual(page.viewport,platform==='mobile'?{width:390,height:844}:{width:1440,height:1000});assert.equal(result.artboard.id,page.id);assert.equal(calls.at(-1).htmlPath,page.htmlPath);
    for(const tail of ['index.html','assets/README.md','css/style.css','js/main.js']){const rel=design.folder+'/'+tail,entry=result.project.workbench.files.find(file=>file.path===rel);assert.equal(entry.designId,design.id);assert.equal((await f.fs.stat(await f.service.target(result.project,rel))).type,'file');}
    const entry=result.project.workbench.files.find(file=>file.pageId===page.id),read=await f.service.execute({action:'file.read',projectId:p,fileId:entry.id});assert.match(read.text,/Prepared initial page/);assert.equal(entry.sha256,page.contentHash);assert.equal((await f.store.artboardGet(p,page.id)).html,read.text);assert.equal((await f.service.execute({action:'file.history',projectId:p,fileId:entry.id})).entries.length,1);
    const extra=(await makePage(f,p,design.id,'Additional')).page;assert.match(extra.htmlPath,new RegExp('^'+design.folder+'/pages/Additional-a-'));assert.equal(extra.htmlPath.endsWith('/index.html'),true);assert.deepEqual((await f.service.project(p)).workbench.designs.find(d=>d.id===design.id).pageIds,[page.id,extra.id]);
  }
  assert.ok(f.fs.writes.every(write=>write.policy===policy&&write.intent));
});

test('initialization recovers an interrupted publish in the same design directory without overwriting existing bytes',async()=>{
  const f=fixture(),raw=await f.store.projectCreate({name:'Interrupted'},undefined,policy),write=f.fs.writeText.bind(f.fs);let interrupt=true,preparations=0;
  f.owner.preparePageHtml=async value=>{preparations++;return value;};
  f.fs.writeText=async(target,...args)=>{if(interrupt&&target.displayPath.endsWith('/project.json')&&args[1]?.kind==='replaceIfVersion'){interrupt=false;throw Object.assign(Error('Interrupted metadata publish'),{code:'TEST_INTERRUPTED'});}return write(target,...args);};
  await assert.rejects(f.service.execute({action:'project.initialize',projectId:raw.id,expectedRevision:raw.revision},{user:true,policy}),code('TEST_INTERRUPTED'));
  const root=f.fs.writes.find(w=>/\/designs\/[^/]+\/index.html$/.test(w.path)).path,custom='<html><body>Keep existing initial page</body></html>',stylesheet=root.replace(/index\.html$/,'css/style.css');await f.fs.external(root,custom);await f.fs.external(stylesheet,'body{color:purple}');const rootVersion=f.fs.files.get(root).version,styleVersion=f.fs.files.get(stylesheet).version;
  const recovered=await f.service.execute({action:'project.initialize',projectId:raw.id,expectedRevision:raw.revision},{user:true,policy});assert.equal(recovered.designs.length,1);assert.equal(recovered.pages.length,1);assert.equal(recovered.page.htmlPath,recovered.design.folder+'/index.html');assert.equal((await f.store.artboardGet(raw.id,recovered.page.id)).html,custom);assert.equal(f.fs.files.get(root).version,rootVersion);assert.equal(f.fs.files.get(stylesheet).version,styleVersion);assert.equal(preparations,1);assert.equal(new Set(f.fs.writes.filter(w=>w.path.includes('/designs/')&&!w.path.endsWith('/designs/README.md')).map(w=>w.path.split('/designs/')[1].split('/')[0])).size,1);
  const again=await mutate(f,raw.id,'project.initialize');assert.deepEqual(again.designs,recovered.designs);assert.deepEqual(again.pages,recovered.pages);assert.equal(f.fs.files.get(root).version,rootVersion);
});

test('concurrent initialization admits one revision and creates only one mobile design for a mobile project',async()=>{
  const f=fixture(),raw=await f.store.projectCreate({name:'Concurrent',platform:'mobile'},undefined,policy),input={action:'project.initialize',projectId:raw.id,expectedRevision:raw.revision},results=await Promise.allSettled([f.service.execute(input,{user:true,policy}),f.service.execute(input,{user:true,policy})]);assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(results.find(r=>r.status==='rejected').reason.code,'VERSION_CONFLICT');const p=await f.service.project(raw.id);assert.equal(p.platform,'mobile');assert.equal(p.workbench.designs.length,1);assert.equal(p.workbench.designs[0].platform,'mobile');assert.equal(p.artboards.length,1);assert.equal(p.artboards[0].platform,'mobile');assert.equal(f.fs.writes.filter(w=>/\/designs\/[^/]+\/index.html$/.test(w.path)).length,1);
});

test('initialization retries preserve edited page revisions and do not resurrect deleted designs',async()=>{
  const f=fixture(),made=await init(f),p=made.project.id,read=await f.service.execute({action:'file.read',projectId:p,path:made.page.htmlPath}),edited=await mutate(f,p,'file.write',{fileId:read.fileId,expectedVersion:read.version,content:'<html><body>Existing user page</body></html>'}),page=edited.pages.find(a=>a.id===made.page.id),version=(await f.service.readAt(edited.project,page.htmlPath)).version;
  const retried=await mutate(f,p,'project.initialize');assert.deepEqual(retried.pages,edited.pages);assert.equal(retried.page.htmlPath,page.htmlPath);assert.equal((await f.service.readAt(retried.project,page.htmlPath)).version,version);assert.equal((await f.store.artboardGet(p,page.id)).html,'<html><body>Existing user page</body></html>');
  await mutate(f,p,'design.delete',{designId:made.design.id});const removed=await mutate(f,p,'project.initialize');assert.equal(removed.designs.length,0);assert.equal(removed.pages.length,0);assert.equal(removed.design,undefined);assert.equal(removed.page,undefined);
});

test('initialization of existing legacy pages preserves IDs and paths without inventing a disconnected root page',async()=>{
  const f=fixture(),raw=await f.store.projectCreate({name:'Legacy initialize'},undefined,policy),old=await f.store.artboardCreate({projectId:raw.id,expectedRevision:raw.revision,name:'Existing',html},undefined,policy),made=await f.service.execute({action:'project.initialize',projectId:raw.id,expectedRevision:old.projectRevision},{user:true,policy});assert.equal(made.designs.length,1);assert.equal(made.pages.length,1);assert.equal(made.page.id,old.artboard.id);assert.equal(made.page.htmlPath,old.artboard.htmlPath);assert.equal((await f.store.artboardGet(raw.id,old.artboard.id)).html,html);assert.equal(await f.fs.stat(await f.service.target(made.project,made.design.folder+'/index.html')),undefined);
});

test('design cloning publishes an actual root page in page order without an extra blank page',async()=>{
  const f=fixture(),made=await init(f),p=made.project.id,second=(await makePage(f,p,made.design.id,'Second',html)).page;await mutate(f,p,'page.reorder',{designId:made.design.id,ids:[second.id,made.page.id]});const cloned=await mutate(f,p,'design.clone',{designId:made.design.id,name:'Clone'}),root=cloned.page;assert.equal(cloned.design.pageIds.length,2);assert.equal(root.id,cloned.design.pageIds[0]);assert.equal(root.htmlPath,cloned.design.folder+'/index.html');assert.equal((await f.store.artboardGet(p,root.id)).html,html);assert.equal(cloned.pages.filter(a=>a.designId===cloned.design.id).length,2);assert.equal(cloned.project.workbench.files.find(file=>file.path===root.htmlPath).pageId,root.id);
});

test('bootstrap writes obey read-only, canonical project and frozen task boundaries',async()=>{
  const f=fixture();await assert.rejects(f.service.execute({action:'project.initialize',name:'Denied'},{user:true,policy:{mode:'read-only',workspaceRoot:'/workspace'}}),code('FS_SANDBOX_DENIED'));assert.equal(f.fs.writes.length,0);
  const made=await init(f),p=made.project.id,revision=made.projectRevision,writes=f.fs.writes.length;await assert.rejects(f.service.execute({action:'design.create',projectId:p,expectedRevision:revision,name:'Out of boundary'},{user:false,policy,target:{projectId:p,scope:'project',writeBoundaryPaths:['docs']}}),code('WRITE_SCOPE'));assert.equal((await f.service.project(p)).revision,revision);assert.equal(f.fs.writes.length,writes);
  await assert.rejects(f.service.execute({action:'page.create',projectId:p,expectedRevision:revision,designId:made.design.id,name:'Not admitted'},{user:false,policy,target:{projectId:p,scope:'page',designId:made.design.id,pageId:made.page.id}}),code('WRITE_SCOPE'));assert.equal(f.fs.writes.length,writes);
  const raw=await f.store.projectCreate({name:'Canonical'},undefined,policy);f.fs.aliases.set(`/workspace/DesignerLibrary/projects/${raw.id}/designs`,'/outside-designs');await assert.rejects(f.service.execute({action:'project.initialize',projectId:raw.id,expectedRevision:raw.revision},{user:true,policy}),code('PROJECT_SCOPE'));assert.equal(f.fs.writes.some(w=>w.path.startsWith('/outside-designs')),false);
});

test('project save location delegates owner registration and does not silently claim success without it',async()=>{const f=fixture();await assert.rejects(f.service.execute({action:'project.initialize',name:'Outside',location:'/other/new'},{policy,user:true}),code('LOCATION_REGISTRATION_REQUIRED'));let registration;f.owner.registerProjectLocation=async(...args)=>{registration=args;};const made=await f.service.execute({action:'project.initialize',name:'Located',saveLocation:'/workspace/selected'},{policy,user:true});assert.equal(registration[0],made.project.id);assert.equal(registration[1],'/workspace/selected');assert.equal(registration[2].policy,policy);assert.equal(registration[2].user,true);});

test('design/page create and reorder keep stable identities; invalid permutations do not publish',async()=>{const f=fixture(),initial=await init(f),p=initial.project.id,a=(await makeDesign(f,p,'Alpha')).design,b=(await makeDesign(f,p,'Beta','mobile')).design;assert.equal(a.folder,'designs/alpha');const first=(await makePage(f,p,a.id,'One')).page,second=(await makePage(f,p,a.id,'Two')).page,ids=[second.id,first.id,...a.pageIds];await mutate(f,p,'page.reorder',{designId:a.id,ids});await mutate(f,p,'design.reorder',{ids:[b.id,a.id,initial.design.id]});const current=await f.service.execute({action:'workspace.open',projectId:p});assert.deepEqual(current.designs.map(d=>d.id),[b.id,a.id,initial.design.id]);assert.deepEqual(current.designs[1].pageIds,ids);await assert.rejects(mutate(f,p,'page.reorder',{designId:a.id,ids:[first.id,first.id]}),code('INVALID_ORDER'));assert.equal((await f.service.project(p)).revision,current.projectRevision);});

test('cross-design cloning copies recursive CSS/image dependencies and rewrites URLs without changing stable DOM IDs',async()=>{const f=fixture(),p=(await init(f)).project.id,source=(await makeDesign(f,p,'Source')).design,target=(await makeDesign(f,p,'Target')).design;await mutate(f,p,'file.create',{path:'resources/theme.css',expectedVersion:null,content:'.logo{background:url("./icon.svg")}',mimeType:'text/css'});await mutate(f,p,'file.create',{path:'resources/icon.svg',expectedVersion:null,content:'<svg xmlns="http://www.w3.org/2000/svg"><rect/></svg>',mimeType:'image/svg+xml'});const a=(await makePage(f,p,source.id,'Original',`<html><head><link href="../../../../resources/theme.css"></head><body><main data-dsh-node="stable-node">Text</main></body></html>`)).page;const result=await mutate(f,p,'page.clone',{pageId:a.id,targetDesignId:target.id,name:'Copied'});const read=await f.service.execute({action:'file.read',projectId:p,path:result.page.htmlPath});assert.match(read.text,/data-dsh-node="stable-node"/);assert.doesNotMatch(read.text,/resources\/theme.css/);const css=result.project.workbench.files.find(x=>x.designId===target.id&&x.mimeType==='text/css');assert.ok(css);const cssRead=await f.service.execute({action:'file.read',projectId:p,fileId:css.id});assert.doesNotMatch(cssRead.text,/\.\/icon.svg/);assert.ok(result.project.workbench.files.some(x=>x.designId===target.id&&x.mimeType==='image/svg+xml'));assert.equal((await f.store.artboardGet(p,a.id)).html.includes('resources/theme.css'),true);});

test('missing copy dependencies fail rather than silently producing broken output',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id,'Page','<html><body><img src="missing.png"></body></html>')).page;const before=await f.service.project(p);await assert.rejects(mutate(f,p,'page.clone',{pageId:a.id}),code('DEPENDENCY_MISSING'));assert.equal((await f.service.project(p)).revision,before.revision);});

test('unregister differs from byte deletion; deleted pages remain available to historical snapshots',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page;await mutate(f,p,'page.delete',{pageId:a.id,deleteFiles:true});assert.ok(await f.fs.stat(await f.store.target(`projects/${p}/${a.htmlPath}`)));assert.equal((await f.service.execute({action:'page.list',projectId:p})).pages.some(page=>page.id===a.id),false);const doc=await mutate(f,p,'file.create',{path:'docs/temp.txt',expectedVersion:null,content:'keep',mimeType:'text/plain'});await mutate(f,p,'file.remove',{fileId:doc.fileId});assert.ok(await f.fs.stat(await f.store.target(`projects/${p}/docs/temp.txt`)));await assert.rejects(f.service.execute({action:'file.read',projectId:p,fileId:doc.fileId}),code('NOT_FOUND'));const other=await mutate(f,p,'file.create',{path:'docs/delete.txt',expectedVersion:null,content:'delete',mimeType:'text/plain'});const read=await f.service.execute({action:'file.read',projectId:p,fileId:other.fileId});await mutate(f,p,'file.remove',{fileId:read.fileId,expectedVersion:read.version,deleteFiles:true});assert.equal(await f.fs.stat(await f.store.target(`projects/${p}/docs/delete.txt`)),undefined);});

test('file IDs and document roles survive rename/move and reference resolution follows exact ID',async()=>{const f=fixture(),p=(await init(f)).project.id,read=await f.service.execute({action:'file.read',projectId:p,path:'docs/requirements.md'});const moved=await mutate(f,p,'file.move',{fileId:read.fileId,expectedVersion:read.version,to:'docs/product-requirements.md'});assert.equal(moved.fileId,read.fileId);assert.equal(moved.file.type,'requirements');assert.equal(moved.project.workbench.requirementsPath,'docs/product-requirements.md');const ref=await f.service.execute({action:'reference.resolve',projectId:p,reference:{resourceId:read.fileId}});assert.equal(ref.file.path,'docs/product-requirements.md');await assert.rejects(f.service.execute({action:'reference.resolve',projectId:p,reference:{resourceId:'f-does-not-exist'}}),code('REFERENCE_NOT_FOUND'));});

test('external file conflicts retain current bytes and persist incoming content under a recovery path',async()=>{const f=fixture(),p=(await init(f)).project.id,read=await f.service.execute({action:'file.read',projectId:p,path:'docs/requirements.md'});await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/docs/requirements.md`,'external edit');let error;try{await mutate(f,p,'file.write',{fileId:read.fileId,expectedVersion:read.version,content:'incoming edit'});}catch(e){error=e;}assert.equal(error.code,'VERSION_CONFLICT');assert.ok(error.details.recovery.path.startsWith('.workbench/conflicts/'));assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:read.fileId})).text,'external edit');const recovery=await f.service.readAt(await f.service.project(p),error.details.recovery.path);assert.equal(JSON.parse(recovery.bytes).incoming,'incoming edit');});

test('page edits retain page and file IDs, old immutable HTML and snapshot reads',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page,read=await f.service.execute({action:'file.read',projectId:p,path:a.htmlPath});const saved=await mutate(f,p,'file.write',{fileId:read.fileId,expectedVersion:read.version,content:html.replace('Original','Updated')});assert.equal(saved.page,undefined);const next=saved.pages.find(x=>x.id===a.id);assert.equal(next.id,a.id);assert.equal(saved.file.id,read.fileId);assert.notEqual(next.htmlPath,a.htmlPath);assert.equal((await f.service.readAt(saved.project,a.htmlPath)).bytes.toString(),html);assert.match((await f.store.artboardGet(p,a.id)).html,/Updated/);});

test('canonical containment, project readonly scopes, model target and read-only policy reject writes',async()=>{const f=fixture(),p=(await init(f)).project.id;await assert.rejects(mutate(f,p,'file.create',{path:'../escape',expectedVersion:null,content:'x'}),code('INVALID_PATH'));f.fs.aliases.set(`/workspace/DesignerLibrary/projects/${p}/docs/link`,'/outside');await assert.rejects(mutate(f,p,'file.create',{path:'docs/link/x.md',expectedVersion:null,content:'x'}),code('PROJECT_SCOPE'));await assert.rejects(mutate(f,p,'file.create',{path:'docs/no.md',expectedVersion:null,content:'x'},{policy:{mode:'read-only',workspaceRoot:'/workspace'}}),code('FS_SANDBOX_DENIED'));await assert.rejects(mutate(f,p,'file.create',{path:'docs/no.md',expectedVersion:null,content:'x'},{user:false,target:{projectId:p,scope:'read'}}),code('WRITE_SCOPE'));const ro=await mutate(f,p,'file.create',{path:'docs/reference.md',expectedVersion:null,content:'readonly',readonly:true});const read=await f.service.execute({action:'file.read',projectId:p,fileId:ro.fileId});await assert.rejects(mutate(f,p,'file.write',{fileId:ro.fileId,expectedVersion:read.version,content:'changed'}),code('READ_ONLY_RESOURCE'));assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:ro.fileId})).text,'readonly');});

test('metadata permissions remain enforced despite alternate viewer modes',async()=>{const f=fixture(),p=(await init(f)).project.id;await f.store.mutate(p,(await f.service.project(p)).revision,'Restrict project',next=>{next.workbench.permissions={readOnlyPaths:['docs'],writablePaths:['assets']};},undefined,policy,false);await assert.rejects(mutate(f,p,'file.create',{path:'docs/no.md',expectedVersion:null,content:'x',mode:'source'}),code('READ_ONLY_RESOURCE'));await assert.rejects(mutate(f,p,'file.create',{path:'other/no.md',expectedVersion:null,content:'x',mode:'preview'}),code('WRITE_SCOPE'));});

test('binding matrix resolves live default/inherit/independent/none and previews actual platform differences without rewriting HTML',async()=>{const f=fixture(),s1=await f.store.systemCreate({name:'Web system',platforms:['web'],tokens:{a:1}}),s2=await f.store.systemCreate({name:'Mobile system',platforms:['mobile'],tokens:{a:2}}),p=(await init(f)).project.id,a=(await makeDesign(f,p,'Inherited')).design,b=(await makeDesign(f,p,'Independent','mobile')).design,c=(await makeDesign(f,p,'None')).design;await mutate(f,p,'binding.set',{designId:b.id,binding:{mode:'independent',systemId:s2.id,version:1}});await mutate(f,p,'binding.set',{designId:c.id,binding:{mode:'none'}});const page=(await makePage(f,p,a.id)).page,hash=page.contentHash;const preview=await f.service.execute({action:'binding.preview',projectId:p,systemId:s1.id,version:1});assert.deepEqual(preview.affected.map(x=>x.designId),[(await f.service.project(p)).workbench.designs[0].id,a.id]);await mutate(f,p,'binding.set',{systemId:s1.id,version:1});assert.equal((await f.service.execute({action:'binding.resolve',projectId:p,designId:a.id})).source,'project');assert.equal((await f.service.execute({action:'binding.resolve',projectId:p,designId:b.id})).systemId,s2.id);assert.equal((await f.service.execute({action:'binding.resolve',projectId:p,designId:c.id})).system,null);await f.store.systemSave({systemId:s1.id,expectedRevision:1,tokens:{a:3}});assert.equal((await f.service.execute({action:'binding.resolve',projectId:p,designId:a.id})).system.tokens.a,3);const change=await f.service.execute({action:'binding.preview',projectId:p,systemId:s2.id,version:1});assert.equal(change.affected.length,2);assert.ok(change.affected.every(item=>item.platformDifference));assert.equal((await f.service.project(p)).artboards.find(x=>x.id===page.id).contentHash,hash);const request=await mutate(f,p,'binding.apply',{designIds:[a.id],pageIds:[page.id]});assert.equal(request.requests[0].status,'pending');assert.equal(request.designs.find(d=>d.id===a.id).appliedSystem.version,2);assert.equal(request.pages.find(x=>x.id===page.id).contentHash,hash);});

test('binding accepts an ID and rejects unknown systems and out-of-scope apply selections',async()=>{const f=fixture(),s=await f.store.systemCreate({name:'Pinned'}),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design;await mutate(f,p,'binding.set',{systemId:s.id});await assert.rejects(mutate(f,p,'binding.set',{designId:d.id,binding:{mode:'independent',systemId:'d-missing'}}),code('NOT_FOUND'));await mutate(f,p,'binding.set',{systemId:s.id,version:1});await assert.rejects(mutate(f,p,'binding.apply',{designIds:[d.id],pageIds:['a-outside']}),code('WRITE_SCOPE'));});

test('state and drafts isolate projects, preserve tabs/camera/target, and never advance project revisions',async()=>{const f=fixture(),p=(await init(f,'P')).project.id,q=(await init(f,'Q')).project.id;const before=await f.service.project(p),state={tabs:[{resourceId:'chat',type:'conversation',preview:false,pinned:true,dirty:true,cursor:{line:4,column:2},scroll:{top:400},mode:'split',camera:{x:5,y:6,zoom:0.7},selection:['node']}],target:{projectId:p,scope:'project'},references:[{resourceId:'a-ref',sourceVersion:1}]};const saved=await f.service.execute({action:'workspace.state.save',projectId:p,expectedVersion:null,state},{policy});await f.service.execute({action:'draft.save',projectId:p,resourceId:'chat',expectedVersion:null,draft:{text:'P unsent',dirty:true}},{policy});await f.service.execute({action:'draft.save',projectId:q,resourceId:'chat',expectedVersion:null,draft:{text:'Q unsent',dirty:true}},{policy});const reopened=new WorkspaceService(f.owner);assert.equal((await reopened.execute({action:'draft.get',projectId:p,resourceId:'chat'})).draft.text,'P unsent');assert.equal((await reopened.execute({action:'draft.get',projectId:q,resourceId:'chat'})).draft.text,'Q unsent');const recovered=await reopened.execute({action:'workspace.state.get',projectId:p});assert.deepEqual(recovered.state.tabs[0].camera,state.tabs[0].camera);assert.equal(recovered.version,saved.version);assert.equal((await f.service.project(p)).revision,before.revision);assert.equal((await reopened.hasUnsavedDrafts(p)).dirty,true);assert.equal((await reopened.execute({action:'workspace.state.get',projectId:q})).state.tabs.length,0);await assert.rejects(reopened.execute({action:'workspace.state.save',projectId:q,expectedVersion:null,state},{policy}),code('PROJECT_SCOPE'));});

test('draft/state CAS conflicts retain both versions; stale remove does not lose drafts',async()=>{const f=fixture(),p=(await init(f)).project.id;const a=await f.service.execute({action:'draft.save',projectId:p,resourceId:'chat',expectedVersion:null,draft:{text:'first'}},{policy});await f.service.execute({action:'draft.save',projectId:p,resourceId:'chat',expectedVersion:a.version,draft:{text:'newest'}},{policy});let error;try{await f.service.execute({action:'draft.save',projectId:p,resourceId:'chat',expectedVersion:a.version,draft:{text:'stale candidate'}},{policy});}catch(e){error=e;}assert.equal(error.code,'VERSION_CONFLICT');assert.ok(error.details.recovery);assert.equal((await f.service.execute({action:'draft.get',projectId:p,resourceId:'chat'})).draft.text,'newest');const record=JSON.parse((await f.service.readAt(await f.service.project(p),error.details.recovery.path)).bytes);assert.equal(record.draft.text,'stale candidate');await assert.rejects(f.service.execute({action:'draft.remove',projectId:p,resourceId:'chat',expectedVersion:a.version},{policy}),code('VERSION_CONFLICT'));const s=await f.service.execute({action:'workspace.state.save',projectId:p,expectedVersion:null,state:{tabs:[],camera:{zoom:1}}},{policy});await assert.rejects(f.service.execute({action:'workspace.state.save',projectId:p,expectedVersion:null,state:{tabs:[],camera:{zoom:2}}},{policy}),code('VERSION_CONFLICT'));assert.equal((await f.service.execute({action:'workspace.state.get',projectId:p})).version,s.version);});

test('binary import/replace/copy uses sandbox shell explicit policy, immutable destinations and stable identity',async()=>{const f=fixture(),p=(await init(f)).project.id,first=await mutate(f,p,'asset.import',{name:'icon.png',mimeType:'image/png',bytesBase64:Buffer.from([137,80,78,71]).toString('base64')}),read=await f.service.execute({action:'file.read',projectId:p,fileId:first.fileId,encoding:'base64'});assert.equal(read.bytesBase64,Buffer.from([137,80,78,71]).toString('base64'));const replaced=await mutate(f,p,'asset.replace',{fileId:first.fileId,expectedVersion:read.version,name:'icon.png',mimeType:'image/png',bytesBase64:Buffer.from([1,2,3]).toString('base64')});assert.equal(replaced.fileId,first.fileId);assert.notEqual(replaced.file.path,first.file.path);assert.ok(await f.fs.stat(await f.store.target(`projects/${p}/${first.file.path}`)));const cloned=await mutate(f,p,'asset.copy',{fileId:first.fileId,to:'assets/local/copied.png'});assert.notEqual(cloned.fileId,first.fileId);assert.ok(f.shellCalls.every(s=>s.sandboxPolicy===policy&&s.onExpiry==='kill'&&s.command.startsWith('node -e')));});

test('exact reference versions and node IDs fail closed after content/identity loss',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page;const reference={resourceId:a.id,nodeId:'stable-node',sourceVersion:1};assert.equal((await f.service.execute({action:'reference.resolve',projectId:p,reference})).node.id,'stable-node');await assert.rejects(f.service.execute({action:'reference.resolve',projectId:p,reference:{...reference,nodeId:'stable'}}),code('REFERENCE_NOT_FOUND'));const read=await f.service.execute({action:'file.read',projectId:p,path:a.htmlPath});await mutate(f,p,'file.write',{fileId:read.fileId,expectedVersion:read.version,content:html.replace('stable-node','new-node')});await assert.rejects(f.service.execute({action:'reference.resolve',projectId:p,reference}),code('REFERENCE_VERSION_CONFLICT'));await assert.rejects(f.service.execute({action:'reference.resolve',projectId:p,reference:{...reference,sourceVersion:2}}),code('REFERENCE_NOT_FOUND'));});

test('source file view respects registered canonical root and write scopes without moving source code',async()=>{const f=fixture(),p=(await init(f)).project.id;await f.fs.external('/external/code/src/app.js','export const x=1;');await f.store.mutate(p,(await f.service.project(p)).revision,'Register external',next=>{next.workbench.sourceProjects=[{id:'r-code',root:'/external/code',readonly:true}];},undefined,policy,false);const read=await f.service.execute({action:'file.read',projectId:p,sourceId:'r-code',path:'src/app.js'});assert.equal(read.type,'source');assert.equal(read.readonly,true);await assert.rejects(mutate(f,p,'file.write',{sourceId:'r-code',path:'src/app.js',expectedVersion:read.version,content:'changed'}),code('READ_ONLY_RESOURCE'));f.fs.aliases.set('/external/code/src/escape','/private');await assert.rejects(f.service.execute({action:'file.read',projectId:p,sourceId:'r-code',path:'src/escape/secret'}),code('SOURCE_SCOPE'));assert.equal((await f.fs.readText(await f.fs.resolve('/external/code/src/app.js'))),'export const x=1;');});

test('project cloning preserves page/history IDs and resources but isolates AI and machine state',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page;await f.service.execute({action:'draft.save',projectId:p,resourceId:'chat',expectedVersion:null,draft:{text:'private unsent'}},{policy});const cloned=await mutate(f,p,'project.clone',{name:'Clone'});assert.notEqual(cloned.project.id,p);assert.ok(cloned.pages.some(page=>page.id===a.id));assert.deepEqual(cloned.pages,(await f.service.project(p)).artboards);assert.deepEqual(cloned.project.history,(await f.service.project(p)).history);assert.equal(cloned.project.aiSessionId,null);assert.equal((await f.service.execute({action:'draft.get',projectId:cloned.project.id,resourceId:'chat'})).draft,null);assert.equal((await f.store.artboardGet(cloned.project.id,a.id)).html,html);const snapshot=cloned.project.history.find(h=>h.summary==='page.create');const restored=await f.store.snapshotRestore({projectId:cloned.project.id,expectedRevision:cloned.projectRevision,snapshotId:snapshot.id});assert.equal(restored.id,cloned.project.id);});

test('file undo/redo restores real immutable bytes and guards against external changes',async()=>{const f=fixture(),p=(await init(f)).project.id;const initial=await mutate(f,p,'file.create',{path:'docs/notes.md',expectedVersion:null,content:'one'});const v1=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});await mutate(f,p,'file.write',{fileId:initial.fileId,expectedVersion:v1.version,content:'two'});const v2=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});const undone=await mutate(f,p,'file.undo',{fileId:initial.fileId,expectedVersion:v2.version});assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId})).text,'one');const redone=await mutate(f,p,'file.redo',{fileId:initial.fileId,expectedVersion:undone.version});assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId})).text,'two');const history=await f.service.execute({action:'file.history',projectId:p,fileId:initial.fileId});assert.equal(history.entries.length,2);await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/docs/notes.md`,'external');await assert.rejects(mutate(f,p,'file.undo',{fileId:initial.fileId,expectedVersion:redone.version}),code('VERSION_CONFLICT'));assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId})).text,'external');});

test('system package import preserves old references while copy/save exposes the current specification and local resource bytes; apply copies selected resources',async()=>{const f=fixture(),system=await f.service.execute({action:'system.import',system:{name:'Kit',platforms:['web'],versions:[{version:1,tokens:{color:'red'},guidelines:'v1',resources:[{id:'r-logo',name:'logo.svg',type:'image',mimeType:'image/svg+xml',content:'<svg><rect/></svg>'}]},{version:2,tokens:{color:'blue'},guidelines:'v2',examples:[{name:'Example',html:'<main>Example</main>'}],resources:[{id:'r-logo',name:'logo.svg',type:'image',mimeType:'image/svg+xml',content:'<svg><circle/></svg>'},{id:'r-font',name:'font.woff2',mimeType:'font/woff2',bytesBase64:Buffer.from([0,1,2]).toString('base64')}]}]}},{policy,user:true});assert.equal(system.versions.length,2);assert.equal(system.versions[0].tokens.color,'red');assert.equal(system.versions[1].resources.length,2);const clone=await f.service.execute({action:'system.copy',systemId:system.id,name:'Copy'},{policy,user:true});assert.notEqual(clone.id,system.id);assert.equal(clone.versions.length,1);assert.notEqual(clone.versions[0].resources[0].path,system.versions[1].resources[0].path);assert.equal(clone.versions[0].resources[0].sha256,system.versions[1].resources[0].sha256);const saved=await f.service.execute({action:'system.save',systemId:system.id,expectedRevision:2,tokens:{color:'green'}},{policy,user:true});assert.equal(saved.versions.length,1);assert.deepEqual(saved.versions[0].resources,system.versions[1].resources);assert.equal(saved.versions[0].tokens.color,'green');const project=await f.service.execute({action:'project.initialize',name:'Use kit',systemId:system.id,systemVersion:2},{policy,user:true}),p=project.project.id,d=(await makeDesign(f,p)).design;await mutate(f,p,'binding.apply',{designIds:[d.id]});const current=await f.service.project(p),resources=current.workbench.files.filter(x=>x.source?.kind==='system');assert.equal(resources.length,2);for(const resource of resources)assert.ok(await f.fs.stat(await f.store.target(`projects/${p}/${resource.path}`)));await assert.rejects(f.service.execute({action:'system.save',projectId:p,systemId:system.id,expectedRevision:3,tokens:{}},{policy,user:false}),code('SHARED_SYSTEM_READ_ONLY'));assert.equal((await f.store.systemGet(system.id)).revision,3);const exported=await f.service.execute({action:'system.export',systemId:system.id,version:2});assert.equal(exported.system.versions.length,1);assert.equal(exported.system.versions[0].resources[1].bytesBase64,Buffer.from([0,1,2]).toString('base64'));const preview=await f.service.execute({action:'system.resource.read',systemId:system.id,version:2,resourceId:'r-logo'});assert.match(preview.previewUrl,/^data:image\/svg\+xml;base64,/);assert.equal(preview.readonly,true);const imported=await f.service.execute({action:'system.import',system:exported.system,name:'Round trip'},{policy,user:true});assert.equal(imported.versions[0].resources[1].sha256,exported.system.versions[0].resources[1].sha256);});

test('design/page scope checks protect metadata even when no file write is involved',async()=>{const f=fixture(),p=(await init(f)).project.id,a=(await makeDesign(f,p,'A')).design,b=(await makeDesign(f,p,'B')).design;await assert.rejects(mutate(f,p,'design.update',{designId:b.id,name:'Forbidden'},{user:false,target:{projectId:p,designId:a.id,scope:'design'}}),code('WRITE_SCOPE'));await assert.rejects(mutate(f,p,'binding.set',{systemId:null},{user:false,target:{projectId:p,designId:a.id,scope:'design'}}),code('WRITE_SCOPE'));assert.equal((await f.service.project(p)).workbench.designs.find(d=>d.id===b.id).name,'B');});

test('stale project CAS also preserves candidate file content and does not touch current bytes',async()=>{const f=fixture(),made=await init(f),p=made.project.id,read=await f.service.execute({action:'file.read',projectId:p,path:'docs/requirements.md'});await makeDesign(f,p);let error;try{await f.service.execute({action:'file.write',projectId:p,expectedRevision:made.projectRevision,expectedVersion:read.version,fileId:read.fileId,content:'candidate'},{policy,user:true});}catch(e){error=e;}assert.equal(error.code,'VERSION_CONFLICT');assert.ok(error.details.recovery);assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:read.fileId})).text,'');const recovery=JSON.parse((await f.service.readAt(await f.service.project(p),error.details.recovery.path)).bytes);assert.equal(recovery.incoming,'candidate');});

test('text read windows transfer bounded UTF-8 byte ranges and historical reads use the exact saved revision',async()=>{const f=fixture(),p=(await init(f)).project.id,value='甲😀乙'.repeat(100000),made=await mutate(f,p,'file.create',{path:'docs/large.md',expectedVersion:null,content:value});let offset=0,out='';for(let i=0;i<3;i++){const part=await f.service.execute({action:'file.read',projectId:p,fileId:made.fileId,offset,limit:7});out+=part.text;offset=part.nextOffset;assert.equal(part.offsetUnit,'utf8-bytes');assert.equal(part.total,Buffer.byteLength(value));}assert.equal(out,value.slice(0,out.length));assert.ok(f.fs.byteRangeReads.every(r=>r.length<=32));const history=await f.service.execute({action:'file.history',projectId:p,fileId:made.fileId}),old=await f.service.execute({action:'file.read',projectId:p,fileId:made.fileId,revisionId:history.entries[0].id,limit:8});assert.equal(old.readonly,true);assert.equal(old.historical,true);assert.equal(old.text,value.slice(0,old.text.length));});

test('replacing assets rewrites active page dependencies while old bytes and HTML remain immutable',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,asset=await mutate(f,p,'asset.import',{name:'icon.svg',mimeType:'image/svg+xml',bytesBase64:Buffer.from('<svg><rect/></svg>').toString('base64')}),relativeAsset='../../../../'+asset.file.path,a=(await makePage(f,p,d.id,'Use asset',`<html><body><img data-dsh-node="image" src="${relativeAsset}"></body></html>`)).page;const read=await f.service.execute({action:'file.read',projectId:p,fileId:asset.fileId}),replaced=await mutate(f,p,'asset.replace',{fileId:asset.fileId,expectedVersion:read.version,name:'icon.svg',mimeType:'image/svg+xml',bytesBase64:Buffer.from('<svg><circle/></svg>').toString('base64')});const current=await f.store.artboardGet(p,a.id);assert.match(current.html,new RegExp(replaced.file.path.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')));assert.doesNotMatch(current.html,new RegExp(asset.file.path.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')));assert.equal((await f.service.readAt(replaced.project,a.htmlPath)).bytes.toString().includes(asset.file.path),true);assert.equal((await f.service.readAt(replaced.project,asset.file.path)).bytes.toString(),'<svg><rect/></svg>');});

test('design clone remaps page navigation in controlled metadata and repeated page copies do not collide on dependencies',async()=>{const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design;await mutate(f,p,'file.create',{path:'assets/icon.svg',expectedVersion:null,content:'<svg/>',mimeType:'image/svg+xml'});const first=(await makePage(f,p,d.id,'First')).page,second=(await makePage(f,p,d.id,'Second',`<html><head><script id="dsh-document-model" type="application/json">${JSON.stringify({schemaVersion:1,interactions:[{pageId:first.id}],designId:d.id})}</script></head><body><img src="../../../../assets/icon.svg"></body></html>`)).page;const cloned=await mutate(f,p,'design.clone',{designId:d.id,name:'Clone'}),secondClone=cloned.pages.find(a=>a.designId===cloned.design.id&&a.name.startsWith('Second'));const read=await f.service.execute({action:'file.read',projectId:p,path:secondClone.htmlPath});assert.equal(read.text.includes(first.id),false);assert.equal(read.text.includes(cloned.pages.find(a=>a.designId===cloned.design.id&&a.name.startsWith('First')).id),true);await mutate(f,p,'page.clone',{pageId:second.id});await mutate(f,p,'page.clone',{pageId:second.id});});

