test('page creation backs up valid original bytes and explicit adoption recovers an externally changed page',async()=>{
  const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page,initial=await f.service.execute({action:'file.read',projectId:p,path:a.htmlPath}),history=await f.service.execute({action:'file.history',projectId:p,fileId:initial.fileId});
  assert.equal(history.entries.length,1);assert.equal((await f.service.readAt(await f.service.project(p),history.entries[0].contentPath)).bytes.toString(),html);
  const remote=html.replace('Original','External program');await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/${a.htmlPath}`,remote);
  const observed=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});assert.equal(observed.externallyModified,true);assert.equal(observed.storedHash,createHash('sha256').update(html).digest('hex'));assert.equal(observed.actualHash,createHash('sha256').update(remote).digest('hex'));
  await assert.rejects(mutate(f,p,'file.write',{fileId:initial.fileId,expectedVersion:observed.version,content:html}),code('VERSION_CONFLICT'));
  const adopted=await f.service.execute({action:'file.reconcile',projectId:p,fileId:initial.fileId,expectedProjectRevision:(await f.service.project(p)).revision,expectedVersion:observed.version,mode:'adopt-external'},{policy,user:true});
  assert.notEqual(adopted.file.path,a.htmlPath);assert.equal(adopted.pages.find(page=>page.id===a.id).revision,2);assert.match((await f.store.artboardGet(p,a.id)).html,/External program/);assert.match((await f.store.artboardGet(p,a.id)).html,/dsh-document-model/);assert.equal((await f.service.readAt(adopted.project,a.htmlPath)).bytes.toString(),remote);
  const current=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});assert.equal(current.externallyModified,false);
  const restored=await mutate(f,p,'file.restore',{fileId:initial.fileId,revisionId:history.entries[0].id,expectedVersion:current.version});assert.equal((await f.store.artboardGet(p,a.id)).html,html);assert.equal((await f.service.readAt(restored.project,a.htmlPath)).bytes.toString(),remote);
});

test('merge preserves external bytes, persisted local draft and candidate then reloads the normalized result',async()=>{
  const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page,initial=await f.service.execute({action:'file.read',projectId:p,path:a.htmlPath}),local=html.replace('Original','Local draft'),remote=html.replace('Original','Remote edit'),merged=html.replace('Original','Remote edit + Local draft');
  const draft=await f.service.execute({action:'draft.save',projectId:p,resourceId:initial.fileId,expectedVersion:null,draft:{content:local,baseVersion:initial.version,dirty:true}},{policy,user:true});await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/${a.htmlPath}`,remote);const observed=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});
  const saved=await f.service.execute({action:'file.reconcile',projectId:p,fileId:initial.fileId,expectedProjectRevision:(await f.service.project(p)).revision,expectedVersion:observed.version,mode:'merge',content:merged},{policy,user:true});
  assert.equal((await f.service.readAt(saved.project,saved.reconciliation.external.contentPath)).bytes.toString(),remote);assert.equal((await f.service.readAt(saved.project,saved.reconciliation.local.contentPath)).bytes.toString(),local);assert.equal((await f.service.readAt(saved.project,saved.reconciliation.candidate.contentPath)).bytes.toString(),merged);
  const reloaded=new WorkspaceService(f.owner),read=await reloaded.execute({action:'file.read',projectId:p,fileId:initial.fileId});assert.match(read.text,/Remote edit \+ Local draft/);assert.equal(read.externallyModified,false);assert.equal(read.actualHash,read.storedHash);assert.equal((await reloaded.execute({action:'draft.get',projectId:p,resourceId:initial.fileId})).version,draft.version);
});

