test('stale and racing reconcile versions reject while preserving candidates and the external original',async()=>{
  const f=fixture(),p=(await init(f)).project.id,d=(await makeDesign(f,p)).design,a=(await makePage(f,p,d.id)).page,initial=await f.service.execute({action:'file.read',projectId:p,path:a.htmlPath}),remote=html.replace('Original','Remote one');await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/${a.htmlPath}`,remote);const old=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId});await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/${a.htmlPath}`,html.replace('Original','Remote two'));let conflict;
  try{await f.service.execute({action:'file.reconcile',projectId:p,fileId:initial.fileId,expectedProjectRevision:(await f.service.project(p)).revision,expectedVersion:old.version,mode:'keep-local',content:html},{policy,user:true});}catch(error){conflict=error;}assert.equal(conflict.code,'VERSION_CONFLICT');assert.ok(conflict.details.recovery);assert.equal((await f.service.project(p)).artboards.find(page=>page.id===a.id).htmlPath,a.htmlPath);
  const observed=await f.service.execute({action:'file.read',projectId:p,fileId:initial.fileId}),before=(await f.service.project(p)).revision,write=f.fs.writeText.bind(f.fs);let raced=false;
  f.fs.writeText=async(target,...args)=>{const result=await write(target,...args);if(!raced&&target.displayPath.includes('/pages/')&&/\/revision-h-.*\.html$/.test(target.displayPath)){raced=true;await f.fs.external(`/workspace/DesignerLibrary/projects/${p}/${a.htmlPath}`,html.replace('Original','Racing external edit'));}return result;};
  await assert.rejects(f.service.execute({action:'file.reconcile',projectId:p,fileId:initial.fileId,expectedProjectRevision:before,expectedVersion:observed.version,mode:'merge',content:html},{policy,user:true}),error=>error.code==='VERSION_CONFLICT'&&!!error.details.recovery);assert.equal(raced,true);assert.equal((await f.service.project(p)).revision,before);assert.match((await f.service.readAt(await f.service.project(p),a.htmlPath)).bytes.toString(),/Racing external edit/);
});

