  assert.equal(await f.fs.readText(await f.fs.resolve(root+'/src/app.js')),'export const value=12;');assert.equal((await f.service.readAt(saved.project,saved.reconciliation.external.contentPath)).bytes.toString(),'export const value=2;');assert.equal((await f.service.readAt(saved.project,saved.reconciliation.local.contentPath)).bytes.toString(),'export const value=10;');assert.equal((await f.service.execute({action:'file.read',projectId:p,sourceId:'r-source',path:'src/app.js'})).externallyModified,false);
  const ordinary=await mutate(f,p,'file.write',{sourceId:'r-source',path:'src/app.js',expectedVersion:saved.version,content:'export const value=13;'});assert.equal(ordinary.version,(await f.service.execute({action:'file.read',projectId:p,sourceId:'r-source',path:'src/app.js'})).version);assert.equal((await f.service.execute({action:'file.read',projectId:p,sourceId:'r-source',path:'src/app.js'})).externallyModified,false);
