test('binary rename and undo preserve opaque bytes rather than decoding them as text',async()=>{const f=fixture(),p=(await init(f)).project.id,bytes=Buffer.from([0xff,0x00,0x80,0x01]),made=await mutate(f,p,'asset.import',{name:'binary.png',mimeType:'image/png',bytesBase64:bytes.toString('base64')}),read=await f.service.execute({action:'file.read',projectId:p,fileId:made.fileId,encoding:'base64'});const moved=await mutate(f,p,'file.move',{fileId:made.fileId,expectedVersion:read.version,to:'assets/renamed.png'});assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:made.fileId,encoding:'base64'})).bytesBase64,bytes.toString('base64'));const replaced=await mutate(f,p,'asset.replace',{fileId:made.fileId,expectedVersion:moved.version,mimeType:'image/png',bytesBase64:Buffer.from([5]).toString('base64')});await mutate(f,p,'file.undo',{fileId:made.fileId,expectedVersion:replaced.version});assert.equal((await f.service.execute({action:'file.read',projectId:p,fileId:made.fileId,encoding:'base64'})).bytesBase64,bytes.toString('base64'));});




test('directory systems accept only rule.md, synchronize AI rules and preserve immutable historical bytes', async () => {
  const f = fixture(), env = {policy, user: true};
  const rule = content => ({logicalPath: 'rule.md', mimeType: 'text/markdown', content});
  const created = await f.service.execute({action: 'system.create', name: 'Minimal directory', format: 'directory', resources: [rule('# 原始规范\n主色为蓝色。')]}, env);
  assert.equal(created.versions[0].format, 'directory');
  assert.equal(created.versions[0].guidelines, '# 原始规范\n主色为蓝色。');
  assert.deepEqual(created.versions[0].tokens, {});
  assert.equal(created.versions[0].resources.length, 1);
  const first = created.versions[0].resources[0];
  f.owner.resources = {}; // Exercise metadata-only user reads while normalizing stored rule bytes.
  const unchanged = await f.service.execute({action: 'system.save', systemId: created.id, expectedRevision: 1, description: 'Only metadata'}, env);
  assert.equal(unchanged.versions[0].guidelines, created.versions[0].guidelines);
  const saved = await f.service.execute({action: 'system.save', systemId: created.id, expectedRevision: 2, resources: [rule('# 新规范\n主色为紫色。'), {logicalPath: 'tokens.json', content: '{"colorPrimary":"#7953cd"}', mimeType: 'application/json'}, {logicalPath: 'css/theme.css', content: ':root{color:purple}', mimeType: 'text/css'}]}, env);
  assert.equal(saved.versions[0].guidelines, '# 新规范\n主色为紫色。');
  assert.equal(saved.versions[0].tokens.colorPrimary, '#7953cd');
  assert.equal((await f.service.execute({action: 'system.resource.read', systemId: created.id, version: 1, resourceId: first.id, encoding: 'base64'}, env)).text, '# 原始规范\n主色为蓝色。');
  const project = await init(f);
  await mutate(f, project.project.id, 'binding.set', {systemId: saved.id, version: 3});
  const binding = await f.service.execute({action: 'binding.resolve', projectId: project.project.id, designId: project.design.id});
  assert.equal(binding.system.guidelines, saved.versions[0].guidelines);
  const copied = await f.service.execute({action: 'system.copy', systemId: saved.id, name: 'Copy'}, env);
  assert.deepEqual(copied.versions.map(item => item.guidelines), saved.versions.map(item => item.guidelines));
  const exported = await f.service.execute({action: 'system.export', systemId: saved.id}, env);
  const imported = await f.service.execute({action: 'system.import', system: exported.system}, env);
  assert.equal(imported.versions[0].format, 'directory');
  assert.equal(imported.versions[0].guidelines, saved.versions[0].guidelines);
  assert.deepEqual(imported.versions[0].resources.map(item => item.logicalPath), ['rule.md', 'tokens.json', 'css/theme.css']);
  const minimal = await f.service.execute({action: 'system.save', systemId: saved.id, expectedRevision: 3, resources: [rule('# 简化规范')]}, env);
  assert.deepEqual(minimal.versions[0].tokens, {});
});

test('directory validation rejects missing, empty, non-UTF8 rules and malformed token files before publishing', async () => {
  const f = fixture(), env = {policy, user: true};
  const base = {action: 'system.create', name: 'Invalid directory', format: 'directory'};
  const cases = [
    [[], 'SYSTEM_RULE_REQUIRED'],
    [[{logicalPath: 'css/rule.md', content: 'Nested rule'}], 'SYSTEM_RULE_REQUIRED'],
    [[{logicalPath: 'rule.md', content: ' \n '}], 'INVALID_INPUT'],
    [[{logicalPath: 'rule.md', bytesBase64: '/w=='}], 'INVALID_UTF8'],
    [[{logicalPath: 'rule.md', content: '# Rules'}, {logicalPath: 'tokens.json', content: '{broken'}], 'INVALID_SYSTEM_JSON'],
  ];
  for (const [resources, errorCode] of cases) await assert.rejects(f.service.execute({...base, resources}, env), code(errorCode));
  assert.equal((await f.store.state()).systems.length, 0);
  await assert.rejects(f.service.execute({action: 'system.import', system: {name: 'Invalid package', platforms: ['web'], versions: [{version: 1, format: 'directory', resources: []}]}}, env), code('SYSTEM_RULE_REQUIRED'));
  assert.equal((await f.store.state()).systems.length, 0);
});

test('extracting a state registers a separately editable sibling with the same relative asset base',async()=>{
  const f=fixture(),start=await init(f),original=start.page,projectId=start.project.id;
  const request={pageId:original.id,expectedArtboardRevision:original.revision,html:'<h1>当前筛选</h1><img src="assets/icon.png">',name:'已筛选'};
  await assert.rejects(mutate(f,projectId,'page.extractState',{...request,expectedArtboardRevision:0}),code('VERSION_CONFLICT'));
  await assert.rejects(mutate(f,projectId,'page.extractState',request,{user:false}),code('USER_ONLY'));
  const {page,project}=await mutate(f,projectId,'page.extractState',request);
  assert.notEqual(page.id,original.id);
  assert.equal(path.dirname(page.htmlPath),path.dirname(original.htmlPath));
  assert.equal(project.artboards.find(p=>p.id===original.id).contentHash,original.contentHash);
  assert.deepEqual(project.workbench.designs[0].pageIds,[original.id,page.id]);
  const result=await f.service.execute({action:'file.read',projectId,path:page.htmlPath},{user:true,policy});
  assert.match(result.content,/当前筛选/);
});

test('project, design and HTML viewport use the bound specification platforms',async()=>{
  const f=fixture();
  for(const [platforms,expected,width] of [[['mobile'],'mobile',390],[['web'],'web',1440],[['mobile','web'],'web',1440]]){
    const system=await f.store.systemCreate({name:expected+' specification',platforms});
    const {project,design,page}=await f.service.execute({action:'project.initialize',name:'Example',systemId:system.id},{user:true,policy});
    assert.equal(project.platform,expected);assert.equal(project.systemId,system.id);assert.equal(design.platform,expected);
    assert.equal(page.viewport.width,width);assert.match(page.htmlPath,/index\.html$/);assert.equal(page.artifact,undefined);
    const next=await mutate(f,project.id,'design.create',{name:'Follow-up'});
    assert.equal(next.page.viewport.width,width);
  }
});
